({
async preview(tab){const h=eval(load("helpers"));return h.ev(tab,"(()=>{const d=document.querySelector('iframe[data-testid=application-preview]')?.contentDocument;return {url:location.href,text:document.body.innerText,preview:d?.body.innerText}})()");},
async editResume(tab){return eval(load("helpers")).ev(tab,"(()=>{const d=document.querySelector('iframe[data-testid=application-preview]')?.contentDocument;const s=d?.querySelector('[data-testid=resumeSection]');const b=s&&[...s.querySelectorAll('button')].find(x=>x.innerText==='Modifier');if(!b)throw Error('No inspected resume edit');b.click();return true})()");},
async continue(tab){return eval(load("helpers")).ev(tab,"(()=>{const b=[...document.querySelectorAll('button')].find(x=>x.offsetWidth&&x.innerText==='Continuer');if(!b||b.disabled)throw Error('No continue');b.click();return true})()");},
async submit(tab,id){const h=eval(load("helpers"));const p=await this.preview(tab);if(!p.preview||!p.text.includes('Relisez votre candidature'))throw Error('No final preview');const r=await tools.exec_command({cmd:"cat "+h.q("job-search/applications/"+id+"/cv-text.txt"),max_output_tokens:8000});const normalize=s=>s.replace(/\s+/g,' ').trim();if(!normalize(p.preview).includes(normalize(r.output)))throw Error('Saved CV preview differs from reviewed PDF');await h.save("job-search/applications/"+id+"/review-preview.json",p);await h.save("job-search/applications/"+id+"/final-form-state-connected.json",await h.inspect(tab));await h.ev(tab,"(()=>{const b=[...document.querySelectorAll('button')].find(x=>x.innerText==='Déposer ma candidature');if(!b||b.disabled)throw Error('No submit');b.click();return true})()");},
async receipt(tab,id){const h=eval(load("helpers"));const p=await h.ev(tab,"({url:location.href,text:document.body.innerText})");if(!p.text.includes('Votre candidature a bien été envoyée.'))return false;await h.save("job-search/applications/"+id+"/confirmation.json",{status:"submitted",round:"jobboards-2026-10-09",submitted_on:"2026-10-12",in_scope:true,...p});text(await tools.exec_command({cmd:".venv/bin/python scripts/record-jobboard-result.py "+h.q(id),max_output_tokens:200}));return true;}
})
